def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while peek()[0] in ('+', '-'):
            op = advance()[0]
            rhs = parse_term()
            if op == '+':
                val = val + rhs
            else:
                val = val - rhs
        return val

    def parse_term():
        val = parse_unary()
        while peek()[0] in ('*', '/'):
            op = advance()[0]
            rhs = parse_unary()
            if op == '*':
                val = val * rhs
            else:
                # integer division truncating toward zero
                a, b = val, rhs
                q = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    q = -q
                val = q
        return val

    def parse_unary():
        if peek()[0] == '-':
            advance()
            return -parse_unary()
        return parse_primary()

    def parse_primary():
        tok_type, tok_val = peek()
        if tok_type == 'NUM':
            advance()
            return tok_val
        elif tok_type == '(':
            advance()
            val = parse_expr()
            if peek()[0] != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return val
        else:
            raise ValueError(f"Unexpected token: {tok_type}")

    result = parse_expr()
    return result

